parsed.tgrl:
grl TeslaModelX_Autopilot {
    actor Driver { goal ReachDestination; goal MaintainControl; goal MonitorRoad; }
    actor AutopilotSystem { goal MaintainLanePosition; goal KeepSpeedSetByDriver; goal AvoidCollision; }
    actor Sensors { goal ProvideAccurateEnvironmentData; }
    actor VisionProcessing { goal DetectLaneMarkings; goal DetectVehiclesAndObjects; }
    actor TACC { goal FollowLeadVehicleAtSafeGap; goal AdjustSpeedAccordingToTraffic; }
    actor Autosteer { goal KeepVehicleCenteredInLane; }
    actor ForwardCollisionWarning { goal AlertDriverOfImminentCollision; }
    actor AutomaticEmergencyBraking { goal ApplyBrakesToMitigateCollision; }
    actor DriverMonitoring { goal DetectDriverHandPresence; goal IssueAlertIfHandsAbsent; }
    actor RoadUsers { goal ShareRoadSafely; }
    actor RoadWorkers { goal PerformWorkWithoutCausingAccidents; }
    actor RoadAgency { goal MaintainRoadMarkingsQuality; goal EnsureSafetyInfrastructure; }
}

